// tools/pdca/meeting-manager.ts import * as fs from 'fs'; import * as path from 'path'; import { Calendar } from './calendar-integration'; import { TicketSystem } from './ticket-integration'; import { ReportGenerator } from './report-generator'; export interface PDCAIssue { id: string; title: string; description: string; category: 'architecture' | 'process' | 'tooling' | 'performance' | 'quality' | 'security'; priority: 'critical' | 'high' | 'medium' | 'low'; impact: 'high' | 'medium' | 'low'; effort: 'small' | 'medium' | 'large'; raisedBy: string; raisedDate: Date; status: 'identified' | 'planned' | 'in-progress' | 'completed' | 'deferred' | 'rejected'; assignee?: string; targetDate?: Date; completionDate?: Date; tags: string[]; } export interface ActionItem { id: string; issueId: string; description: string; assignee: string; dueDate: Date; status: 'pending' | 'in-progress' | 'completed' | 'overdue'; priority: 'critical' | 'high' | 'medium' | 'low'; estimatedEffort: number; // hours actualEffort?: number; // hours blockers: string[]; dependencies: string[]; notes: string[]; ticketId?: string; } export interface PDCAMeeting { id: string; date: Date; type: 'monthly' | 'sprint-retro' | 'quarterly' | 'adhoc'; attendees: string[]; facilitator: string; agenda: AgendaItem[]; issues: PDCAIssue[]; actionItems: ActionItem[]; decisions: Decision[]; metrics: MeetingMetrics; duration: number; // minutes nextMeetingDate?: Date; notes: string; } export interface AgendaItem { id: string; title: string; description: string; timeAllocation: number; // minutes presenter: string; type: 'review' | 'discussion' | 'decision' | 'planning'; materials: string[]; } export interface Decision { id: string; title: string; description: string; rationale: string; alternatives: string[]; decisionMaker: string; impactedTeams: string[]; implementationPlan: string; reviewDate?: Date; } export interface MeetingMetrics { issuesRaised: number; issuesResolved: number; actionItemsCreated: number; actionItemsCompleted: number; decisionsMade: number; attendanceRate: number; satisfactionScore?: number; } export class PDCAMeetingManager { private meetings: Map<string, PDCAMeeting> = new Map(); private issues: Map<string, PDCAIssue> = new Map(); private actionItems: Map<string, ActionItem> = new Map(); private calendar: Calendar; private ticketSystem: TicketSystem; private reportGenerator: ReportGenerator; constructor() { this.calendar = new Calendar(); this.ticketSystem = new TicketSystem(); this.reportGenerator = new ReportGenerator(); this.loadPersistedData(); } async scheduleMeeting( type: PDCAMeeting['type'], date: Date, facilitator: string, attendees: string[] ): Promise<string> { const meetingId = this.generateMeetingId(type, date); const agenda = await this.generateAgenda(type); const openIssues = this.getOpenIssues(); const overdueActions = this.getOverdueActionItems(); const meeting: PDCAMeeting = { id: meetingId, date, type, attendees, facilitator, agenda, issues: openIssues, actionItems: overdueActions, decisions: [], metrics: this.initializeMetrics(), duration: this.getDefaultDuration(type), notes: '', }; this.meetings.set(meetingId, meeting); // Schedule in calendar await this.calendar.createEvent({ title: `PDCA Meeting - ${type}`, date, duration: meeting.duration, attendees, description: this.generateMeetingDescription(meeting), }); await this.persistData(); return meetingId; } async addIssue(issue: Omit<PDCAIssue, 'id' | 'raisedDate' | 'status'>): Promise<string> { const issueId = this.generateIssueId();
 const pdcaIssue: PDCAIssue = {
 ...issue,
 id: issueId,
 raisedDate: new Date(),
 status: 'identified',
 };

 this.issues.set(issueId, pdcaIssue);
 await this.persistData();

 // Auto-assign to next meeting if appropriate
 const nextMeeting = this.getNextScheduledMeeting();
 if (nextMeeting && this.shouldIncludeInNextMeeting(pdcaIssue)) {
 nextMeeting.issues.push(pdcaIssue);
 }

 return issueId;
 }

 async createActionItem(
 issueId: string,
 actionItem: Omit<ActionItem, 'id' | 'issueId' | 'status'>
 ): Promise<string> {
 const actionId = this.generateActionId();
 const action: ActionItem = {
 ...actionItem,
 id: actionId,
 issueId,
 status: 'pending',
 };

 this.actionItems.set(actionId, action);

 // Create ticket in external system
 if (action.priority === 'critical' || action.priority === 'high') {
 action.ticketId = await this.ticketSystem.createTicket({
 title: action.description,
 assignee: action.assignee,
 dueDate: action.dueDate,
 priority: action.priority,
 labels: ['pdca', 'action-item'],
 });
 }

 await this.persistData();
 return actionId;
 }

 async updateActionItemStatus(
 actionId: string,
 status: ActionItem['status'],
 notes?: string,
 actualEffort?: number
 ): Promise<void> {
 const action = this.actionItems.get(actionId);
 if (!action) {
 throw new Error(`Action item ${actionId} not found`);
 }

 action.status = status;
 if (notes) {
 action.notes.push(`${new Date().toISOString()}: ${notes}`);
 }
 if (actualEffort !== undefined) {
 action.actualEffort = actualEffort;
 }
 if (status === 'completed') {
 action.completionDate = new Date();
 }

 // Update external ticket
 if (action.ticketId) {
 await this.ticketSystem.updateTicket(action.ticketId, {
 status: this.mapStatusToTicketSystem(status),
 notes,
 });
 }

 await this.persistData();
 }

 async conductMeeting(meetingId: string): Promise<void> {
 const meeting = this.meetings.get(meetingId);
 if (!meeting) {
 throw new Error(`Meeting ${meetingId} not found`);
 }

 console.log(`\n🎯 Starting PDCA Meeting: ${meeting.type}`);
 console.log(`📅 Date: ${meeting.date.toISOString()}`);
 console.log(`👥 Facilitator: ${meeting.facilitator}`);
 console.log(`📋 Attendees: ${meeting.attendees.join(', ')}\n`);

 // Execute agenda items
 for (const agendaItem of meeting.agenda) {
 await this.executeAgendaItem(meeting, agendaItem);
 }

 // Generate meeting summary
 const summary = await this.generateMeetingSummary(meeting);
 console.log(summary);

 // Schedule next meeting if needed
 if (meeting.type === 'monthly') {
 const nextDate = new Date(meeting.date);
 nextDate.setMonth(nextDate.getMonth() + 1);
 meeting.nextMeetingDate = nextDate;

 await this.scheduleMeeting(meeting.type, nextDate, meeting.facilitator, meeting.attendees);
 }

 await this.persistData();
 }

 async generateProgressReport(): Promise<{
 summary: any;
 issueAnalysis: any;
 actionItemAnalysis: any;
 trends: any;
 }> {
 const allIssues = Array.from(this.issues.values());
 const allActions = Array.from(this.actionItems.values());
 const recentMeetings = Array.from(this.meetings.values())
 .filter(m => m.date > new Date(Date.now() - 90 * 24 * 60 * 60 * 1000)) // Last 90 days
 .sort((a, b) => b.date.getTime() - a.date.getTime());

 const summary = {
 totalIssues: allIssues.length,
 resolvedIssues: allIssues.filter(i => i.status === 'completed').length,
 totalActionItems: allActions.length,
 completedActionItems: allActions.filter(a => a.status === 'completed').length,
 recentMeetings: recentMeetings.length,
 averageMeetingDuration: recentMeetings.reduce((sum, m) => sum + m.duration, 0) / recentMeetings.length,
 };

 const issueAnalysis = {
 byCategory: this.groupByCategory(allIssues),
 byPriority: this.groupByPriority(allIssues),
 byStatus: this.groupByStatus(allIssues),
 resolutionTime: this.calculateAverageResolutionTime(allIssues),
 };

 const actionItemAnalysis = {
 byAssignee: this.groupActionsByAssignee(allActions),
 byPriority: this.groupByPriority(allActions),
 completionRate: this.calculateCompletionRate(allActions),
 averageEffort: this.calculateAverageEffort(allActions),
 overdueItems: allActions.filter(a => a.status !== 'completed' && a.dueDate < new Date()),
 };

 const trends = {
 issueCreationTrend: this.calculateIssueCreationTrend(allIssues),
 resolutionTrend: this.calculateResolutionTrend(allIssues),
 meetingEffectiveness: this.calculateMeetingEffectiveness(recentMeetings),
 };

 return {
 summary,
 issueAnalysis,
 actionItemAnalysis,
 trends,
 };
 }

 private async generateAgenda(type: PDCAMeeting['type']): Promise<AgendaItem[]> {
 const baseAgenda: AgendaItem[] = [
 {
 id: 'welcome',
 title: 'Welcome & Introductions',
 description: 'Meeting opening and participant introductions',
 timeAllocation: 5,
 presenter: 'facilitator',
 type: 'review',
 materials: [],
 },
 {
 id: 'previous-actions',
 title: 'Previous Action Items Review',
 description: 'Review progress on action items from previous meeting',
 timeAllocation: 15,
 presenter: 'facilitator',
 type: 'review',
 materials: ['action-items-report'],
 },
 ];

 // Add type-specific agenda items
 if (type === 'monthly') {
 baseAgenda.push(
 {
 id: 'architecture-health',
 title: 'Architecture Health Review',
 description: 'Review current architecture metrics and health indicators',
 timeAllocation: 20,
 presenter: 'architect',
 type: 'review',
 materials: ['architecture-dashboard', 'metrics-report'],
 },
 {
 id: 'issue-discussion',
 title: 'Issue Discussion & Planning',
 description: 'Discuss new issues and plan solutions',
 timeAllocation: 30,
 presenter: 'facilitator',
 type: 'discussion',
 materials: ['issue-list', 'impact-analysis'],
 },
 {
 id: 'improvement-planning',
 title: 'Improvement Planning',
 description: 'Plan improvement initiatives and assign action items',
 timeAllocation: 20,
 presenter: 'facilitator',
 type: 'planning',
 materials: ['improvement-backlog'],
 }
 );
 } else if (type === 'sprint-retro') {
 baseAgenda.push(
 {
 id: 'sprint-review',
 title: 'Sprint Review',
 description: 'Review sprint outcomes and learnings',
 timeAllocation: 15,
 presenter: 'scrum-master',
 type: 'review',
 materials: ['sprint-report'],
 },
 {
 id: 'what-went-well',
 title: 'What Went Well',
 description: 'Identify and celebrate successes',
 timeAllocation: 10,
 presenter: 'team',
 type: 'discussion',
 materials: [],
 },
 {
 id: 'what-could-improve',
 title: 'What Could Be Improved',
 description: 'Identify improvement opportunities',
 timeAllocation: 15,
 presenter: 'team',
 type: 'discussion',
 materials: [],
 }
 );
 }

 baseAgenda.push(
 {
 id: 'next-steps',
 title: 'Next Steps & Action Items',
 description: 'Define action items and next steps',
 timeAllocation: 15,
 presenter: 'facilitator',
 type: 'planning',
 materials: [],
 },
 {
 id: 'closing',
 title: 'Meeting Closing',
 description: 'Meeting summary and closing',
 timeAllocation: 5,
 presenter: 'facilitator',
 type: 'review',
 materials: [],
 }
 );

 return baseAgenda;
 }

 private async executeAgendaItem(meeting: PDCAMeeting, agendaItem: AgendaItem): Promise<void> {
 console.log(`\n📋 ${agendaItem.title} (${agendaItem.timeAllocation} min)`);
 console.log(` ${agendaItem.description}`);

 // Simulate agenda item execution based on type
 switch (agendaItem.id) {
 case 'previous-actions':
 await this.reviewPreviousActions(meeting);
 break;
 case 'architecture-health':
 await this.reviewArchitectureHealth(meeting);
 break;
 case 'issue-discussion':
 await this.discussIssues(meeting);
 break;
 case 'improvement-planning':
 await this.planImprovements(meeting);
 break;
 default:
 console.log(` ✅ Agenda item completed`);
 }
 }

 private async reviewPreviousActions(meeting: PDCAMeeting): Promise<void> {
 const previousActions = Array.from(this.actionItems.values())
 .filter(a => a.dueDate <= meeting.date);

 console.log(` 📊 Reviewing ${previousActions.length} action items:`);

 for (const action of previousActions) {
 const status = action.status === 'completed' ? '✅' : 
 action.status === 'in-progress' ? '🔄' : 
 action.dueDate < meeting.date ? '🔴' : '⏳';

 console.log(` ${status} ${action.description} (${action.assignee})`);

 if (action.status === 'completed') {
 meeting.metrics.actionItemsCompleted++;
 }
 }
 }

 private async reviewArchitectureHealth(meeting: PDCAMeeting): Promise<void> {
 // This would integrate with actual architecture monitoring
 console.log(` 📈 Architecture Health Metrics:`);
 console.log(` • Code Quality Score: 85/100`);
 console.log(` • Technical Debt: 12 hours`);
 console.log(` • Test Coverage: 87%`);
 console.log(` • Performance Score: 92/100`);
 console.log(` • Security Score: 89/100`);
 }

 private async discussIssues(meeting: PDCAMeeting): Promise<void> {
 console.log(` 🔍 Discussing ${meeting.issues.length} issues:`);

 for (const issue of meeting.issues) {
 console.log(` • ${issue.title} (${issue.priority} priority)`);

 // Simulate issue discussion and action planning
 if (issue.status === 'identified') {
 issue.status = 'planned';
 meeting.metrics.issuesRaised++;

 // Create action item for high priority issues
 if (issue.priority === 'critical' || issue.priority === 'high') {
 await this.createActionItem(issue.id, {
 description: `Resolve: ${issue.title}`,
 assignee: issue.assignee || 'to-be-assigned',
 dueDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 1 week
 priority: issue.priority,
 estimatedEffort: this.estimateEffort(issue),
 blockers: [],
 dependencies: [],
 notes: [`Created from PDCA meeting ${meeting.id}`],
 });

 meeting.metrics.actionItemsCreated++;
 }
 }
 }
 }

 private async planImprovements(meeting: PDCAMeeting): Promise<void> {
 console.log(` 📋 Planning improvement initiatives:`);

 const improvementAreas = [
 'Automated testing coverage',
 'CI/CD pipeline optimization',
 'Documentation updates',
 'Performance monitoring',
 'Security scanning automation',
 ];

 for (const area of improvementAreas) {
 console.log(` • ${area}`);
 }
 }

 private async generateMeetingSummary(meeting: PDCAMeeting): Promise<string> {
 const summary = `
📋 PDCA Meeting Summary
=====================
Date: ${meeting.date.toISOString()}
Type: ${meeting.type}
Duration: ${meeting.duration} minutes
Attendees: ${meeting.attendees.length}

📊 Metrics:
• Issues Raised: ${meeting.metrics.issuesRaised}
• Issues Resolved: ${meeting.metrics.issuesResolved}
• Action Items Created: ${meeting.metrics.actionItemsCreated}
• Action Items Completed: ${meeting.metrics.actionItemsCompleted}
• Decisions Made: ${meeting.metrics.decisionsMade}

🎯 Next Meeting: ${meeting.nextMeetingDate?.toISOString() || 'TBD'}
`;

 return summary;
 }

 private getOpenIssues(): PDCAIssue[] {
 return Array.from(this.issues.values())
 .filter(issue => issue.status !== 'completed' && issue.status !== 'rejected');
 }

 private getOverdueActionItems(): ActionItem[] {
 return Array.from(this.actionItems.values())
 .filter(action => 
 action.status !== 'completed' && 
 action.dueDate < new Date()
 );
 }

 private getNextScheduledMeeting(): PDCAMeeting | undefined {
 return Array.from(this.meetings.values())
 .filter(meeting => meeting.date > new Date())
 .sort((a, b) => a.date.getTime() - b.date.getTime())[0];
 }

 private shouldIncludeInNextMeeting(issue: PDCAIssue): boolean {
 return issue.priority === 'critical' || issue.priority === 'high';
 }

 private generateMeetingId(type: string, date: Date): string {
 return `pdca-${type}-${date.toISOString().split('T')[0]}`;
 }

 private generateIssueId(): string {
 return `issue-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
 }

 private generateActionId(): string {
 return `action-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
 }

 private initializeMetrics(): MeetingMetrics {
 return {
 issuesRaised: 0,
 issuesResolved: 0,
 actionItemsCreated: 0,
 actionItemsCompleted: 0,
 decisionsMade: 0,
 attendanceRate: 100,
 };
 }

 private getDefaultDuration(type: PDCAMeeting['type']): number {
 switch (type) {
 case 'monthly': return 90;
 case 'sprint-retro': return 60;
 case 'quarterly': return 120;
 case 'adhoc': return 45;
 default: return 60;
 }
 }

 private generateMeetingDescription(meeting: PDCAMeeting): string {
 return `PDCA Meeting - ${meeting.type}\n\nAgenda:\n${meeting.agenda.map(item => `• ${item.title} (${item.timeAllocation}min)`).join('\n')}`;
 }

 private mapStatusToTicketSystem(status: ActionItem['status']): string {
 switch (status) {
 case 'pending': return 'Open';
 case 'in-progress': return 'In Progress';
 case 'completed': return 'Done';
 case 'overdue': return 'Blocked';
 default: return 'Open';
 }
 }

 private estimateEffort(issue: PDCAIssue): number {
 const effortMap = {
 small: 4,
 medium: 16,
 large: 40,
 };
 return effortMap[issue.effort] || 8;
 }

 private groupByCategory<T extends { category: string }>(items: T[]) {
 return items.reduce((acc, item) => {
 acc[item.category] = (acc[item.category] || 0) + 1;
 return acc;
 }, {} as Record<string, number>);
 }

 private groupByPriority<T extends { priority: string }>(items: T[]) {
 return items.reduce((acc, item) => {
 acc[item.priority] = (acc[item.priority] || 0) + 1;
 return acc;
 }, {} as Record<string, number>);
 }

 private groupByStatus<T extends { status: string }>(items: T[]) {
 return items.reduce((acc, item) => {
 acc[item.status] = (acc[item.status] || 0) + 1;
 return acc;
 }, {} as Record<string, number>);
 }

 private groupActionsByAssignee(actions: ActionItem[]) {
 return actions.reduce((acc, action) => {
 acc[action.assignee] = (acc[action.assignee] || 0) + 1;
 return acc;
 }, {} as Record<string, number>);
 }

 private calculateAverageResolutionTime(issues: PDCAIssue[]): number {
 const resolvedIssues = issues.filter(i => i.status === 'completed' && i.completionDate);
 if (resolvedIssues.length === 0) return 0;

 const totalTime = resolvedIssues.reduce((sum, issue) => {
 const resolutionTime = issue.completionDate!.getTime() - issue.raisedDate.getTime();
 return sum + resolutionTime;
 }, 0);

 return totalTime / resolvedIssues.length / (24 * 60 * 60 * 1000); // Convert to days
 }

 private calculateCompletionRate(actions: ActionItem[]): number {
 if (actions.length === 0) return 0;
 const completed = actions.filter(a => a.status === 'completed').length;
 return (completed / actions.length) * 100;
 }

 private calculateAverageEffort(actions: ActionItem[]): number {
 const actionsWithEffort = actions.filter(a => a.actualEffort !== undefined);
 if (actionsWithEffort.length === 0) return 0;

 const totalEffort = actionsWithEffort.reduce((sum, action) => sum + action.actualEffort!, 0);
 return totalEffort / actionsWithEffort.length;
 }

 private calculateIssueCreationTrend(issues: PDCAIssue[]): any[] {
 // Group issues by month for trend analysis
 const monthlyData = new Map<string, number>();

 for (const issue of issues) {
 const monthKey = issue.raisedDate.toISOString().substr(0, 7); // YYYY-MM
 monthlyData.set(monthKey, (monthlyData.get(monthKey) || 0) + 1);
 }

 return Array.from(monthlyData.entries())
 .sort(([a], [b]) => a.localeCompare(b))
 .map(([month, count]) => ({ month, count }));
 }

 private calculateResolutionTrend(issues: PDCAIssue[]): any[] {
 const resolvedIssues = issues.filter(i => i.status === 'completed' && i.completionDate);
 const monthlyData = new Map<string, number>();

 for (const issue of resolvedIssues) {
 const monthKey = issue.completionDate!.toISOString().substr(0, 7);
 monthlyData.set(monthKey, (monthlyData.get(monthKey) || 0) + 1);
 }

 return Array.from(monthlyData.entries())
 .sort(([a], [b]) => a.localeCompare(b))
 .map(([month, count]) => ({ month, count }));
 }

 private calculateMeetingEffectiveness(meetings: PDCAMeeting[]): number {
 if (meetings.length === 0) return 0;

 const totalEffectiveness = meetings.reduce((sum, meeting) => {
 const actionItemsRatio = meeting.metrics.actionItemsCompleted / Math.max(meeting.metrics.actionItemsCreated, 1);
 const issueResolutionRatio = meeting.metrics.issuesResolved / Math.max(meeting.metrics.issuesRaised, 1);
 const attendanceScore = meeting.metrics.attendanceRate / 100;

 return sum + (actionItemsRatio + issueResolutionRatio + attendanceScore) / 3;
 }, 0);

 return (totalEffectiveness / meetings.length) * 100;
 }

 private async loadPersistedData(): Promise<void> {
 try {
 const dataPath = './data/pdca-data.json';
 if (fs.existsSync(dataPath)) {
 const data = JSON.parse(fs.readFileSync(dataPath, 'utf8'));

 // Load meetings
 if (data.meetings) {
 for (const meeting of data.meetings) {
 this.meetings.set(meeting.id, {
 ...meeting,
 date: new Date(meeting.date),
 nextMeetingDate: meeting.nextMeetingDate ? new Date(meeting.nextMeetingDate) : undefined,
 });
 }
 }

 // Load issues
 if (data.issues) {
 for (const issue of data.issues) {
 this.issues.set(issue.id, {
 ...issue,
 raisedDate: new Date(issue.raisedDate),
 targetDate: issue.targetDate ? new Date(issue.targetDate) : undefined,
 completionDate: issue.completionDate ? new Date(issue.completionDate) : undefined,
 });
 }
 }

 // Load action items
 if (data.actionItems) {
 for (const action of data.actionItems) {
 this.actionItems.set(action.id, {
 ...action,
 dueDate: new Date(action.dueDate),
 completionDate: action.completionDate ? new Date(action.completionDate) : undefined,
 });
 }
 }
 }
 } catch (error) {
 console.warn('Failed to load persisted PDCA data:', error);
 }
 }

 private async persistData(): Promise<void> {
 try {
 const data = {
 meetings: Array.from(this.meetings.values()),
 issues: Array.from(this.issues.values()),
 actionItems: Array.from(this.actionItems.values()),
 lastUpdated: new Date().toISOString(),
 };

 const dataPath = './data/pdca-data.json';
 const dir = path.dirname(dataPath);

 if (!fs.existsSync(dir)) {
 fs.mkdirSync(dir, { recursive: true });
 }

 fs.writeFileSync(dataPath, JSON.stringify(data, null, 2));
 } catch (error) {
 console.error('Failed to persist PDCA data:', error);
 }
 }
}
