gs.filter(f => f.severity === 'MEDIUM').length, low: findings.filter(f => f.severity === 'LOW').length, }, byCategory: this.groupFindingsByCategory(findings), findings, }; this.logger.log(`Security review report: ${JSON.stringify(report)}`); } private groupFindingsByCategory(findings: ReviewFinding[]): Record<string, number> { const grouped: Record<string, number> = {}; for (const finding of findings) { const rule = this.securityRules.get(finding.ruleId); if (rule) { grouped[rule.category] = (grouped[rule.category] || 0) + 1; } } return grouped; } private initializeSecurityRules(): void { const rules: SecurityReviewRule[] = [ { id: 'SQL_INJECTION', category: 'INPUT_VALIDATION', pattern: /\$\{.*\}.*query|query.*\$\{.*\}/i, description: 'Potential SQL injection vulnerability', severity: 'CRITICAL', guidance: 'Use parameterized queries or ORM methods to prevent SQL injection', examples: { vulnerable: 'const query = `SELECT * FROM users WHERE id = ${userId}`;', secure: 'const user = await userRepository.findOne({ where: { id: userId } });', }, }, { id: 'XSS_RISK', category: 'OUTPUT_ENCODING', pattern: /innerHTML\s*=|dangerouslySetInnerHTML/i, description: 'Potential XSS vulnerability', severity: 'HIGH', guidance: 'Use proper HTML encoding or sanitization for dynamic content', examples: { vulnerable: 'element.innerHTML = userInput;', secure: 'element.textContent = userInput; // or use DOMPurify.sanitize()', }, }, { id: 'HARDCODED_SECRET', category: 'CRYPTOGRAPHY', pattern: /(password|secret|key|token)\s*[:=]\s*["'][^"']*["']/i, description: 'Hardcoded secret detected', severity: 'CRITICAL', guidance: 'Use environment variables or secure secret management for sensitive data', examples: { vulnerable: 'const apiKey = "sk-1234567890abcdef";', secure: 'const apiKey = process.env.API_KEY;', }, }, { id: 'WEAK_CRYPTO', category: 'CRYPTOGRAPHY', pattern: / (md5|sha1) /i, description: 'Weak cryptographic algorithm', severity: 'HIGH', guidance: 'Use strong cryptographic algorithms like SHA-256 or bcrypt', examples: { vulnerable: 'crypto.createHash("md5").update(password).digest("hex");', secure: 'await bcrypt.hash(password, 12);', }, }, { id: 'INSUFFICIENT_LOGGING', category: 'LOGGING', pattern: /console\.(log|error|warn)/i, description: 'Using console for logging', severity: 'MEDIUM', guidance: 'Use proper logging framework with appropriate log levels', examples: { vulnerable: 'console.log("User logged in:", userId);', secure: 'this.logger.log("User logged in", { userId });', }, }, { id: 'SENSITIVE_DATA_LOG', category: 'LOGGING', pattern: /(password|token|secret|key).*log|log.*(password|token|secret|key)/i, description: 'Potential sensitive data in logs', severity: 'HIGH', guidance: 'Never log sensitive information like passwords or tokens', examples: { vulnerable: 'logger.info("Login attempt", { password, username });', secure: 'logger.info("Login attempt", { username });', }, }, { id: 'ERROR_INFORMATION_LEAK', category: 'ERROR_HANDLING', pattern: /throw\s+new\s+Error\(\s*error\s*\)|res\.status\(500\)\.send\(error\)/i, description: 'Potential information leak in error messages', severity: 'MEDIUM', guidance: 'Sanitize error messages before sending to client', examples: { vulnerable: 'throw new Error(error);', secure: 'throw new Error("Invalid input provided");', }, }, { id: 'MISSING_AUTH_CHECK', category: 'AUTHORIZATION', pattern: /@Controller|@Get|@Post|@Put|@Delete/, description: 'Check for missing authentication/authorization', severity: 'HIGH', guidance: 'Ensure all endpoints have appropriate guards or decorators', examples: { vulnerable: '@Get("/admin") getAdminData() { ... }', secure: '@UseGuards(JwtAuthGuard, RolesGuard) @Roles("admin") @Get("/admin") getAdminData() { ... }', }, }, { id: 'CORS_MISCONFIGURATION', category: 'AUTHENTICATION', pattern: /origin:\s*\*|credentials:\s*true.*origin:\s*\*/s, description: 'Potential CORS misconfiguration', severity: 'HIGH', guidance: 'Avoid using wildcard origin with credentials enabled', examp