// src/design/security-architecture.service.ts import { Injectable, Logger } from '@nestjs/common'; interface SecurityRequirement { id: string; category: 'CONFIDENTIALITY' | 'INTEGRITY' | 'AVAILABILITY' | 'AUTHENTICATION' | 'AUTHORIZATION' | 'AUDITABILITY'; description: string; implementation: string; verification: string; riskLevel: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL'; } interface ArchitectureComponent { name: string; type: 'SERVICE' | 'DATABASE' | 'CACHE' | 'QUEUE' | 'GATEWAY' | 'STORAGE'; securityRequirements: string[]; dataClassification: 'PUBLIC' | 'INTERNAL' | 'CONFIDENTIAL' | 'RESTRICTED'; trustBoundary: boolean; communicationProtocols: string[]; authenticationMethods: string[]; } interface ThreatModel { component: string; threats: Threat[]; mitigations: Mitigation[]; residualRisk: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL'; } interface Threat { id: string; category: 'SPOOFING' | 'TAMPERING' | 'REPUDIATION' | 'INFORMATION_DISCLOSURE' | 'DENIAL_OF_SERVICE' | 'ELEVATION_OF_PRIVILEGE'; description: string; likelihood: 'LOW' | 'MEDIUM' | 'HIGH'; impact: 'LOW' | 'MEDIUM' | 'HIGH'; riskScore: number; } interface Mitigation { threatId: string; description: string; implementation: string; effectiveness: 'LOW' | 'MEDIUM' | 'HIGH'; cost: 'LOW' | 'MEDIUM' | 'HIGH'; } @Injectable() export class SecurityArchitectureService { private readonly logger = new Logger(SecurityArchitectureService.name); private readonly securityRequirements = new Map<string, SecurityRequirement>(); private readonly threatModels = new Map<string, ThreatModel>(); constructor() { this.initializeSecurityRequirements(); } async reviewArchitecture( components: ArchitectureComponent[], dataFlows: any[], trustBoundaries: any[] ): Promise<{ securityAssessment: any; threatModels: ThreatModel[]; recommendations: string[]; }> { this.logger.log('Starting security architecture review'); const securityAssessment = await this.assessSecurityPosture(components); const threatModels = await this.generateThreatModels(components, dataFlows); const recommendations = await this.generateSecurityRecommendations( securityAssessment, threatModels ); return { securityAssessment, threatModels, recommendations, }; } async generateThreatModel(component: ArchitectureComponent): Promise<ThreatModel> { const threats = await this.identifyThreats(component); const mitigations = await this.identifyMitigations(threats, component); const residualRisk = this.calculateResidualRisk(threats, mitigations); const threatModel: ThreatModel = { component: component.name, threats, mitigations, residualRisk, }; this.threatModels.set(component.name, threatModel); return threatModel; } async validateSecurityRequirements( component: ArchitectureComponent ): Promise<{ compliant: boolean; missingRequirements: string[]; recommendations: string[]; }> { const requiredSecurityControls = this.getRequiredSecurityControls(component); const implementedControls = component.securityRequirements; const missingRequirements = requiredSecurityControls.filter( req => !implementedControls.includes(req) ); const recommendations = this.generateImplementationRecommendations( component, missingRequirements ); return { compliant: missingRequirements.length === 0, missingRequirements, recommendations, }; } async generateSecurityDesignDocument( projectName: string, components: ArchitectureComponent[], threatModels: ThreatModel[] ): Promise<string> { let document = `# Security Design Document: ${projectName}

`; document += '## Executive Summary

'; document += this.generateExecutiveSummary(components, threatModels); document += '
## Security Architecture Overview

'; document += this.generateArchitectureOverview(components); document += '
## Threat Models

'; document += this.generateThreatModelSection(threatModels); document += '
## Security Controls

'; document += this.generateSecurityControlsSection(components); document += '
## Risk Assessment

'; document += this.generateRiskAssessmentSection(threatModels); document += '
## Implementation Recommendations

'; document += this.generateImplementationSection(components, threatModels); return document; } private async assessSecurityPosture(components: ArchitectureComponent[]): Promise<any> { const assessment = { overallRisk: 'MEDIUM', componentAssessments: new Map(), securityGaps: [], strengths: [], }; for (const component of components) { const componentAssessment = await this.assessComponent(component); assessment.componentAssessments.set(component.name, componentAssessment); if (componentAssessment.risk === 'HIGH' || componentAssessment.risk === 'CRITICAL') { assessment.securityGaps.push({ component: component.name, issues: componentAssessment.issues, }); } } return assessment; } private async assessComponent(component: ArchitectureComponent): Promise<any> { const requiredControls = this.getRequiredSecurityControls(component); const missingControls = requiredControls.filter( control => !component.securityRequirements.includes(control) ); const risk = this.calculateComponentRisk(component, missingControls); return { risk, implementedControls: component.securityRequirements.length, missingControls: missingControls.length, issues: missingControls, }; } private async generateThreatModels( components: ArchitectureComponent[], dataFlows: any[] ): Promise<ThreatModel[]> { const threatModels: ThreatModel[] = []; for (const component of components) { const threatModel = await this.generateThreatModel(component); threatModels.push(threatModel); } return threatModels; } private async identifyThreats(component: ArchitectureComponent): Promise<Threat[]> { const threats: Threat[] = []; // STRIDE threat modeling const strideThreats = { SPOOFING: this.getSpoofingThreats(component), TAMPERING: this.getTamperingThreats(component), REPUDIATION: this.getRepudiationThreats(component), INFORMATION_DISCLOSURE: this.getInformationDisclosureThreats(component), DENIAL_OF_SERVICE: this.getDenialOfServiceThreats(component), ELEVATION_OF_PRIVILEGE: this.getElevationOfPrivilegeThreats(component), }; for (const [category, categoryThreats] of Object.entries(strideThreats)) { threats.push(...categoryThreats.map(threat => ({ ...threat, category: category as any, riskScore: this.calculateRiskScore(threat.likelihood, threat.impact), }))); } return threats; } private getSpoofingThreats(component: ArchitectureComponent): Partial<Threat>[] { const threats: Partial<Threat>[] = []; if (!component.authenticationMethods.includes('MUTUAL_TLS')) { threats.push({ id: `SPOOF_${component.name}_001`, description: 'Attacker could impersonate legitimate service', likelihood: 'MEDIUM', impact: 'HIGH', }); } if (component.type === 'SERVICE' && !component.authenticationMethods.includes('JWT')) { threats.push({ id: `SPOOF_${component.name}_002`, description: 'Unauthorized access to service endpoints', likelihood: 'HIGH', impact: 'HIGH', }); } return threats; } private getTamperingThreats(component: ArchitectureComponent): Partial<Threat>[] { const threats: Partial<Threat>[] = []; if (!component.communicationProtocols.includes('TLS')) { threats.push({ id: `TAMPER_${component.name}_001`, description: 'Data could be modified in transit', likelihood: 'HIGH', impact: 'HIGH', }); } if (component.type === 'DATABASE' && !component.securityRequirements.includes('ENCRYPTION_AT_REST')) { threats.push({ id: `TAMPER_${component.name}_002`, description: 'Stored data could be modified', likelihood: 'MEDIUM', impact: 'HIGH', }); } return threats; } private getRepudiationThreats(component: ArchitectureComponent): Partial<Threat>[] { const threats: Partial<Threat>[] = []; if (!component.securityRequirements.includes('AUDIT_LOGGING')) { threats.push({ id: `REPUDIATE_${component.name}_001`, description: 'Actions cannot be traced to specific users', likelihood: 'MEDIUM', impact: 'MEDIUM', }); } return threats; } private getInformationDisclosureThreats(component: ArchitectureComponent): Partial<Threat>[] { const threats: Partial<Threat>[] = []; if (component.dataClassification === 'CONFIDENTIAL' || component.dataClassification === 'RESTRICTED') { if (!component.securityRequirements.includes('ENCRYPTION_AT_REST')) { threats.push({ id: `DISCLOSURE_${component.name}_001`, description: 'Sensitive data could be exposed at rest', likelihood: 'MEDIUM', impact: 'HIGH', }); } if (!component.communicationProtocols.includes('TLS')) { threats.push({ id: `DISCLOSURE_${component.name}_002`, description: 'Sensitive data could be exposed in transit', likelihood: 'HIGH', impact: 'HIGH', }); } } return threats; } private getDenialOfServiceThreats(component: ArchitectureComponent): Partial<Threat>[] { const threats: Partial<Threat>[] = []; if (!component.securityRequirements.includes('RATE_LIMITING')) { threats.push({ id: `DOS_${component.name}_001`, description: 'Service could be overwhelmed by excessive requests', likelihood: 'HIGH', impact: 'MEDIUM', }); } return threats; } private getElevationOfPrivilegeThreats(component: ArchitectureComponent): Partial<Threat>[] { const threats: Partial<Threat>[] = []; if (!component.securityRequirements.includes('RBAC')) { threats.push({ id: `PRIVILEGE_${component.name}_001`, description: 'Users could gain unauthorized access levels', likelihood: 'MEDIUM', impact: 'HIGH', }); } return threats; } private async identifyMitigations(threats: Threat[], component: ArchitectureComponent): Promise<Mitigation[]> { const mitigations: Mitigation[] = []; for (const threat of threats) { const threatMitigations = this.getMitigationsForThreat(threat, component); mitigations.push(...threatMitigations); } return mitigations; } private getMitigationsForThreat(threat: Threat, component: ArchitectureComponent): Mitigation[] { const mitigations: Mitigation[] = []; switch (threat.category) { case 'SPOOFING': mitigations.push({ threatId: threat.id, description: 'Implement mutual TLS authentication', implementation: 'Configure mTLS certificates and validation', effectiveness: 'HIGH', cost: 'MEDIUM', }); break; case 'TAMPERING': mitigations.push({ threatId: threat.id, description: 'Use TLS for all communications', implementation: 'Enable TLS 1.3 with strong cipher suites', effectiveness: 'HIGH', cost: 'LOW', }); break; case 'INFORMATION_DISCLOSURE': mitigations.push({ threatId: threat.id, description: 'Implement encryption at rest', implementation: 'Use AES-256 encryption for stored data', effectiveness: 'HIGH', cost: 'MEDIUM', }); break; case 'DENIAL_OF_SERVICE': mitigations.push({ threatId: threat.id, description: 'Implement rate limiting', implementation: 'Configure API gateway rate limits and circuit breakers', effectiveness: 'MEDIUM', cost: 'LOW', }); break; } return mitigations; } private calculateRiskScore(likelihood: string, impact: string): number { const likelihoodValues = { LOW: 1, MEDIUM: 2, HIGH: 3 }; const impactValues = { LOW: 1, MEDIUM: 2, HIGH: 3 }; return likelihoodValues[likelihood] * impactValues[impact]; } private calculateResidualRisk(threats: Threat[], mitigations: Mitigation[]): 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL' { // Calculate residual risk after mitigations const highRiskThreats = threats.filter(t => t.riskScore >= 6); const mitigatedThreats = highRiskThreats.filter(t => mitigations.some(m => m.threatId === t.id && m.effectiveness === 'HIGH') ); const unmitigatedHighRisk = highRiskThreats.length - mitigatedThreats.length; if (unmitigatedHighRisk > 2) return 'CRITICAL'; if (unmitigatedHighRisk > 1) return 'HIGH'; if (unmitigatedHighRisk > 0) return 'MEDIUM'; return 'LOW'; } private calculateComponentRisk(component: ArchitectureComponent, missingControls: string[]): string { const criticalControls = ['ENCRYPTION_AT_REST', 'TLS', 'AUTHENTICATION']; const criticalMissing = missingControls.filter(control => criticalControls.includes(control)); if (criticalMissing.length > 1) return 'CRITICAL'; if (criticalMissing.length > 0) return 'HIGH'; if (missingControls.length > 3) return 'MEDIUM'; return 'LOW'; } private getRequiredSecurityControls(component: ArchitectureComponent): string[] { const baseControls = ['AUTHENTICATION', 'AUTHORIZATION', 'AUDIT_LOGGING']; const typeSpecificControls = { SERVICE: ['RATE_LIMITING', 'INPUT_VALIDATION', 'OUTPUT_ENCODING'], DATABASE: ['ENCRYPTION_AT_REST', 'ACCESS_CONTROL', 'BACKUP_ENCRYPTION'], CACHE: ['ACCESS_CONTROL', 'DATA_EXPIRATION'], STORAGE: ['ENCRYPTION_AT_REST', 'ACCESS_CONTROL', 'VERSIONING'], }; const dataClassificationControls = { CONFIDENTIAL: ['ENCRYPTION_AT_REST', 'ENCRYPTION_IN_TRANSIT', 'ACCESS_LOGGING'], RESTRICTED: ['ENCRYPTION_AT_REST', 'ENCRYPTION_IN_TRANSIT', 'ACCESS_LOGGING', 'DLP'], }; return [ ...baseControls, ...(typeSpecificControls[component.type] || []), ...(dataClassificationControls[component.dataClassification] || []), ]; } private generateImplementationRecommendations( component: ArchitectureComponent, missingRequirements: string[] ): string[] { return missingRequirements.map(requirement => { switch (requirement) { case 'ENCRYPTION_AT_REST': return `Implement AES-256 encryption for ${component.name} data storage`; case 'RATE_LIMITING': return `Configure rate limiting for ${component.name} API endpoints`; case 'AUDIT_LOGGING': return `Enable comprehensive audit logging for ${component.name}`; default: return `Implement ${requirement} for ${component.name}`; } }); } private async generateSecurityRecommendations( securityAssessment: any, threatModels: ThreatModel[] ): Promise<string[]> { const recommendations: string[] = []; // High-level recommendations based on assessment if (securityAssessment.overallRisk === 'HIGH' || securityAssessment.overallRisk === 'CRITICAL') { recommendations.push('Conduct immediate security remediation for critical components'); } // Specific recommendations from threat models for (const threatModel of threatModels) { if (threatModel.residualRisk === 'HIGH' || threatModel.residualRisk === 'CRITICAL') { recommendations.push(`Address high-risk threats in ${threatModel.component}`); } } return recommendations; } // Document generation methods private generateExecutiveSummary(compone